export const loadoutPreset = (id: string) => LOADOUT_PRESETS.find((p) => p.id === id) ?? LOADOUT_PRESETS[0]!;

export type LoadoutState = {
  mission: LoadoutMission;
  players: string[];
  order: "snake" | "linear";
  picks: Record<string, Record<string, string>>; // player -> slotId -> itemId
  spent: Record<string, number>;
  turn: number;
  done: boolean;
  /** Random-roll mode: show a few random options per slot instead of the whole pool. */
  roll?: { n: number; seed: number; rerolls: Record<string, number>; offers: Record<string, string[]> };
};

export function poolItems(pool: string): Item[] {
  return getCatalog(pool);
}

const total = (s: LoadoutState) => s.players.length * s.mission.slots.length;

export function init(mission: LoadoutMission, players: string[], order: "snake" | "linear" = "snake", roll?: { n: number; rerolls: number; seed: number }): LoadoutState {
  return {
    roll: roll ? { n: roll.n, seed: roll.seed, rerolls: Object.fromEntries(players.map((p) => [p, roll.rerolls])), offers: {} } : undefined,
    mission,
    players,
    order,
    picks: Object.fromEntries(players.map((p) => [p, {}])),
    spent: Object.fromEntries(players.map((p) => [p, 0])),
    turn: 0,
    done: false,
  };
}

export function turnPlayer(s: LoadoutState): string {
  const n = s.players.length;
  const round = Math.floor(s.turn / n);
  const idx = s.turn % n;
  const rev = s.order === "snake" && round % 2 === 1;
  return s.players[rev ? n - 1 - idx : idx]!;
}

export const takenItems = (s: LoadoutState) => new Set(Object.values(s.picks).flatMap((m) => Object.values(m)));

export const openSlots = (s: LoadoutState, player: string) => s.mission.slots.filter((sl) => !s.picks[player]![sl.id]);

/**
 * Conservative cheapest cost to fill `slots` for `player`: other players still
 * need cheap items too, so take the (rivals+1)-th cheapest untaken item per slot.
 */
function reserveFor(s: LoadoutState, player: string, slots: LoadoutSlot[]): number {
  const used = new Set(takenItems(s));
  let sum = 0;
  for (const slot of slots) {
    const rivals = s.players.filter((p) => p !== player && !s.picks[p]![slot.id]).length;
    const ranked = poolItems(slot.pool)
      .filter((it) => !used.has(it.id))
      .map((it) => ({ id: it.id, price: priceOf(it, slot.priceStat) }))
      .sort((x, y) => x.price - y.price);
    const choice = ranked[Math.min(rivals, ranked.length - 1)];
    if (!choice) return Infinity;
    used.add(choice.id);
    sum += choice.price;
  }
  return sum;
}

/** Most this player may pay for `forSlot` now while still being able to afford every other open slot. */
export function maxSpend(s: LoadoutState, player: string, forSlot?: string): number {
  const left = s.mission.budget - s.spent[player]!;
  const open = openSlots(s, player);
  const others = open.filter((sl) => sl.id !== (forSlot ?? open[0]?.id));
  return left - reserveFor(s, player, others);
}

export function validate(s: LoadoutState, slotId: string, itemId: string): { ok: true; price: number } | { ok: false; reason: string } {
  if (s.done) return { ok: false, reason: "Loadout complete" };
  const player = turnPlayer(s);
  const slot = s.mission.slots.find((x) => x.id === slotId);
  if (!slot) return { ok: false, reason: "Unknown slot" };
  if (s.picks[player]![slotId]) return { ok: false, reason: "Slot already filled" };
  const item = poolItems(slot.pool).find((i) => i.id === itemId);
  if (!item) return { ok: false, reason: "Not in this slot's pool" };
  if (takenItems(s).has(itemId)) return { ok: false, reason: "Already taken" };
  const offered = s.roll?.offers[slotId];
  if (s.roll && offered && !offered.includes(itemId)) return { ok: false, reason: "Not one of your rolled options" };
  const price = priceOf(item, slot.priceStat);
  const cap = maxSpend(s, player, slotId);
  if (price > cap) return { ok: false, reason: `Too expensive — max $${Math.max(0, cap)}` };
  return { ok: true, price };
}

export function pick(s: LoadoutState, slotId: string, itemId: string): LoadoutState {
  const v = validate(s, slotId, itemId);
  if (!v.ok) return s;
  const player = turnPlayer(s);
  const turn = s.turn + 1;
  return {
    ...s,
    picks: { ...s.picks, [player]: { ...s.picks[player], [slotId]: itemId } },
    spent: { ...s.spent, [player]: s.spent[player]! + v.price },
    turn,
    done: turn >= total(s),
    roll: s.roll ? { ...s.roll, offers: {} } : undefined,
  };
}

/** Random affordable options for a slot, never empty while anything is affordable. */
function sampleOffer(s: LoadoutState, slotId: string, seed: number): [string[], number] {
  const slot = s.mission.slots.find((x) => x.id === slotId)!;
  const bare: LoadoutState = { ...s, roll: { ...s.roll!, offers: {} } };
  const ok = poolItems(slot.pool).filter((i) => validate(bare, slotId, i.id).ok).map((i) => i.id);
  const [shuffled, next] = shuffle(ok, seed);
  return [shuffled.slice(0, s.roll!.n), next];
}

/** Make sure an offer exists for this slot (free the first time). */
export function rollFor(s: LoadoutState, slotId: string): LoadoutState {
  if (!s.roll || s.done || s.roll.offers[slotId] || s.picks[turnPlayer(s)]![slotId]) return s;
  const [offer, seed] = sampleOffer(s, slotId, s.roll.seed);
  return { ...s, roll: { ...s.roll, seed, offers: { ...s.roll.offers, [slotId]: offer } } };
}

/** Spend a reroll token to redraw this slot's options. */
export function rerollSlot(s: LoadoutState, slotId: string): LoadoutState {
  if (!s.roll || s.done) return s;
  const p = turnPlayer(s);
  if ((s.roll.rerolls[p] ?? 0) <= 0 || s.picks[p]![slotId]) return s;
  const [offer, seed] = sampleOffer(s, slotId, s.roll.seed);
  return { ...s, roll: { ...s.roll, seed, offers: { ...s.roll.offers, [slotId]: offer }, rerolls: { ...s.roll.rerolls, [p]: s.roll.rerolls[p]! - 1 } } };
}

export function itemFor(s: LoadoutState, player: string, slotId: string): Item | undefined {
  const id = s.picks[player]?.[slotId];
  const slot = s.mission.slots.find((x) => x.id === slotId);
  return id && slot ? poolItems(slot.pool).find((i) => i.id === id) : undefined;
}

export type AiPlan = { slot: string; item: string; seed: number; offers: Record<string, string[]> };

/** What the AI would do right now, including the random rolls it saw (so the UI can show them). */
export function planAuto(s: LoadoutState): AiPlan | null {
  if (s.done) return null;
  const player = turnPlayer(s);
  const bare: LoadoutState = { ...s, roll: s.roll ? { ...s.roll, offers: {} } : undefined };
  let best: { slot: string; item: string; value: number } | null = null;
  let seed = s.roll?.seed ?? 0;
  const offers: Record<string, string[]> = {};
  for (const slot of openSlots(s, player)) {
    let candidates = poolItems(slot.pool);
    if (s.roll) {
      const [ids, ns] = sampleOffer(bare, slot.id, seed);
      seed = ns;
      offers[slot.id] = ids;
      candidates = candidates.filter((i) => ids.includes(i.id));
    }
    for (const item of candidates) {
      const v = validate(bare, slot.id, item.id);
      if (!v.ok) continue;
      const q = itemScore(item, slot.scoreWeights);
      const wants = s.mission.boss.weaknesses.filter((w) => item.tags.includes(w)).length;
      const value = q + wants * 6 - v.price * 3;
      if (!best || value > best.value) best = { slot: slot.id, item: item.id, value };
    }
  }
  return best ? { slot: best.slot, item: best.item, seed, offers } : null;
}

/** Best-value pick for the AI (or timeout): maximise slot score per dollar with a quality bias. */
export function autoPick(s: LoadoutState): LoadoutState {
  const plan = planAuto(s);
  if (!plan) return { ...s, done: true };
  return pick({ ...s, roll: s.roll ? { ...s.roll, seed: plan.seed, offers: {} } : undefined }, plan.slot, plan.item);
}

export function scoreLoadout(mission: LoadoutMission, items: { slot: LoadoutSlot; item: Item }[]) {
  if (!items.length) return { total: 0, quality: 0, coverage: 0, covered: [] as string[] };
  const quality = items.reduce((a, { slot, item }) => a + itemScore(item, slot.scoreWeights), 0) / mission.slots.length;
  const tags = new Set(items.flatMap((x) => x.item.tags));
  const covered = mission.boss.weaknesses.filter((w) => tags.has(w));
  const coverage = covered.length / Math.max(1, mission.boss.weaknesses.length);
  return {
    total: Math.round(Math.min(100, quality * 0.8 + coverage * 24) * 10) / 10,
    quality: Math.round(quality),
    coverage: Math.round(coverage * 100),
    covered,
  };
}
